clc;
clear;
close all;

[x, Fs] = audioread('C:\Users\sahil\Downloads\PR wav.mpeg');
x=mean(x,2);
t = (0:length(x)-1)/Fs;

plot(t,x); %[output:29ab9e3f]
xlabel('Time (s)'); %[output:29ab9e3f]
ylabel('Amplitude'); %[output:29ab9e3f]
title('Original Audio Signal x(t)'); %[output:29ab9e3f]
grid on; %[output:29ab9e3f]

%% Listen Original
soundsc(x,Fs);

pause(length(x)/Fs + 1);

%% Question 1 - Separate T1 and T2
idx1 = t <= 0.5;
idx2 = t > 0.5 & t <= 1.0;

figure; %[output:8a39d180]

subplot(2,1,1); %[output:8a39d180]
plot(t(idx1),x(idx1)); %[output:8a39d180]
xlabel('Time (s)'); %[output:8a39d180]
ylabel('Amplitude'); %[output:8a39d180]
title('First Letter - T1'); %[output:8a39d180]
grid on; %[output:8a39d180]

subplot(2,1,2); %[output:8a39d180]
plot(t(idx2),x(idx2)); %[output:8a39d180]
xlabel('Time (s)'); %[output:8a39d180]
ylabel('Amplitude'); %[output:8a39d180]
title('Second Letter - T2'); %[output:8a39d180]
grid on; %[output:8a39d180]

%% Question 2 - Advance by 0.5 sec
advance = round(0.5*Fs);

y1 = [x(advance+1:end); zeros(advance,1)];

t1 = (0:length(y1)-1)/Fs;

figure; %[output:7e007872]
plot(t1,y1); %[output:7e007872]
xlabel('Time (s)'); %[output:7e007872]
ylabel('Amplitude'); %[output:7e007872]
title('Advance: y(t) = x(t+0.5)'); %[output:7e007872]
grid on; %[output:7e007872]

soundsc(y1,Fs);

pause(length(y1)/Fs + 1);

%% Question 3 - Downsampling by 10
y2 = x(1:10:end);

Fs2 = Fs/10;

t2 = (0:length(y2)-1)/Fs2;

figure; %[output:28f212cd]
plot(t2,y2); %[output:28f212cd]
xlabel('Time (s)'); %[output:28f212cd]
ylabel('Amplitude'); %[output:28f212cd]
title('Downsampled Signal'); %[output:28f212cd]
grid on; %[output:28f212cd]

soundsc(y2,Fs2);

pause(length(y2)/Fs2 + 1);

%% Question 4 - Time Reversal
y3 = flipud(x);

t3 = (0:length(y3)-1)/Fs;

figure; %[output:6984b5ca]
plot(t3,y3); %[output:6984b5ca]
xlabel('Time (s)'); %[output:6984b5ca]
ylabel('Amplitude'); %[output:6984b5ca]
title('Flipped Signal: y(t) = x(-t)'); %[output:6984b5ca]
grid on; %[output:6984b5ca]

soundsc(y3,Fs);

